import re

def parse_ini(text: str) -> dict[str, dict[str, str]]:
    sections_raw = {}
    current_section = None
    last_key = None

    lines = text.splitlines()

    for line_num, line in enumerate(lines, 1):
        stripped_line = line.strip()

        # Rule 3: Ignore empty or full-line comments
        if not stripped_line or stripped_line[0] in ';#':
            continue

        # Rule 6: Continuation lines (start with whitespace)
        if line and not line[0].isspace() is False and current_section is not None and last_key is not None:
            # This is a continuation line
            val = _strip_inline_comment(stripped_line)
            sections_raw[current_section][last_key] += "\n" + val
            continue

        # Rule 1: Section headers
        if stripped_line.startswith('[') and stripped_line.endswith(']'):
            current_section = stripped_line[1:-1].strip()
            if current_section not in sections_raw:
                sections_raw[current_section] = {}
            last_key = None
            continue

        # Rule 2: Key-Value pairs
        delimiter = None
        eq_idx = line.find('=')
        col_idx = line.find(':')

        if eq_idx != -1 and (col_idx == -1 or eq_idx < col_idx):
            delimiter = '='
            split_idx = eq_idx
        elif col_idx != -1:
            delimiter = ':'
            split_idx = col_idx
        else:
            # Rule 10: Malformed line
            raise ValueError(f"Malformed line at {line_num}: {line}")

        if current_section is None:
            # Rule 10: Key before section
            raise ValueError(f"Key found before section header at line {line_num}")

        key_part = line[:split_idx].strip().lower()
        val_part = line[split_idx + 1:].strip()

        # Rule 4 & 5: Handle quotes and inline comments
        value = _parse_value(val_part)

        sections_raw[current_section][key_part] = value
        last_key = key_part

    # Rule 8: Handle DEFAULT inheritance
    default_vals = sections_raw.pop('DEFAULT', {})
    result = {}
    for section, keys in sections_raw.items():
        merged = default_vals.copy()
        merged.update(keys)
        result[section] = merged

    # Rule 9: Interpolation
    memo = {}
    path = set()

    def resolve(section, key):
        state_key = (section, key)
        if state_key in memo:
            return memo[state_key]
        if state_key in path:
            raise ValueError("Interpolation cycle detected")

        path.add(state_key)

        # Get the raw value
        try:
            val = result[section][key]
        except KeyError:
            raise KeyError(f"Key '{key}' not found in section '{section}'")

        # Recursive interpolation using regex
        def replace_match(match):
            content = match.group(1)
            if ':' in content:
                s_name, k_name = content.split(':', 1)
                if s_name not in result:
                    raise KeyError(f"Section '{s_name}' not found")
                return resolve(s_name, k_name)
            else:
                return resolve(section, content)

        final_val = re.sub(r'\$\{(.*?)\}', replace_match, val)
        path.remove(state_key)
        memo[state_key] = final_val
        return final_val

    # Final pass to resolve all values
    final_result = {}
    for section in result:
        final_result[section] = {}
        for key in result[section]:
            final_result[section][key] = resolve(section, key)

    return final_result

def _strip_inline_comment(text: str) -> str:
    # Simple strip for continuation lines as they aren't quoted wrappers
    # but still follow the " whitespace + #/; " rule
    match = re.search(r'\s+[;#]', text)
    if match:
        return text[:match.start()].strip()
    return text.strip()

def _parse_value(val: str) -> str:
    # Rule 5: Double quoted values
    if val.startswith('"') and val.endswith('"'):
        return val[1:-1]

    # Rule 4: Inline comments (whitespace followed by ; or #)
    # We use a regex to find the first occurrence of ' #' or ' ;'
    match = re.search(r'\s+[;#]', val)
    if match:
        return val[:match.start()].strip()

    return val.strip()
