from collections import OrderedDict

class TTLCache:
    def __init__(self, capacity, ttl, clock):
        self.capacity = capacity
        self.ttl = ttl
        self.clock = clock
        self.cache = OrderedDict()  # key -> (value, expiry)
        self.stats_counts = {"hits": 0, "misses": 0, "evictions": 0, "expirations": 0}

    def put(self, key, value):
        if self.capacity <= 0:
            return

        now = self.clock()
        expiry = now + self.ttl

        if key in self.cache:
            self.cache.move_to_end(key)
            self.cache[key] = (value, expiry)
            return

        # Remove all expired entries before checking capacity
        self._cleanup_expired(now)

        if len(self.cache) >= self.capacity:
            # Evict Least Recently Used (first item in OrderedDict)
            self.cache.popitem(last=False)
            self.stats_counts["evictions"] += 1

        self.cache[key] = (value, expiry)

    def get(self, key, default=None):
        if self.capacity <= 0:
            self.stats_counts["misses"] += 1
            return default

        now = self.clock()
        if key not in self.cache:
            self.stats_counts["misses"] += 1
            return default

        val, expiry = self.cache[key]
        if now >= expiry:
            del self.cache[key]
            self.stats_counts["expirations"] += 1
            self.stats_counts["misses"] += 1
            return default

        self.cache.move_to_end(key)
        self.stats_counts["hits"] += 1
        return val

    def _cleanup_expired(self, now):
        # We must iterate over a copy of keys because we are modifying the dict
        keys = list(self.cache.keys())
        for k in keys:
            _, expiry = self.cache[k]
            if now >= expiry:
                del self.cache[k]
                self.stats_counts["expirations"] += 1

    def __len__(self):
        now = self.clock()
        count = 0
        for _, expiry in self.cache.values():
            if now < expiry:
                count += 1
        return count

    def stats(self):
        return self.stats_counts.copy()
