def summarize_ranges(nums: list[int]) -> str:
    if not nums:
        return ""

    # Sort and remove duplicates
    sorted_nums = sorted(set(nums))
    n = len(sorted_nums)
    result = []
    i = 0

    while i < n:
        start = i
        # Find the end of the consecutive run
        while i + 1 < n and sorted_nums[i + 1] == sorted_nums[i] + 1:
            i += 1

        end = i
        run_length = end - start + 1

        if run_length >= 3:
            # Collapse run of 3 or more
            result.append(f"{sorted_nums[start]}..{sorted_nums[end]}")
        else:
            # List individually for runs of 1 or 2
            for j in range(start, end + 1):
                result.append(str(sorted_nums[j]))

        i += 1

    return ",".join(result)
